<?php $max = max(1, ...array_map(fn($r) => max((int)$r['views'], (int)$r['downloads']), $series ?: [['views' => 0, 'downloads' => 0]])); ?>
<div class="be_page"><div class="be_pagehead"><h1><?= e(t('menu.statistics')) ?></h1></div>
<form class="be_filters" method="get" action="<?= e(url('statistics')) ?>"><label><?= e(t('stat.from')) ?> <input type="date" name="from" value="<?= e($from) ?>"></label><label><?= e(t('stat.to')) ?> <input type="date" name="to" value="<?= e($to) ?>"></label><button class="be_btn" type="submit"><?= e(t('dash.filter')) ?></button></form>
<div class="be_cards">
<div class="be_stat"><span><?= (int)$m['abstract_view'] ?></span><?= e(t('stat.views')) ?></div><div class="be_stat"><span><?= (int)$m['galley_download'] ?></span><?= e(t('stat.downloads')) ?></div><div class="be_stat"><span><?= (int)$recv ?></span><?= e(t('stat.received')) ?></div>
<div class="be_stat"><span><?= (int)$accepted ?></span><?= e(t('stat.accepted')) ?></div><div class="be_stat"><span><?= (int)$declined ?></span><?= e(t('stat.declined')) ?></div><div class="be_stat"><span><?= $rate === null ? '-' : (int)$rate . '%' ?></span><?= e(t('stat.rate')) ?></div><div class="be_stat"><span><?= $days === null ? '-' : e($days) ?></span><?= e(t('stat.days')) ?></div></div>
<div class="be_card"><h2><?= e(t('stat.by_month')) ?></h2><?php if (!$series): ?><p class="muted"><?= e(t('stat.no_data')) ?></p><?php else: ?><div class="be_chart" role="img" aria-label="<?= e(t('stat.by_month')) ?>"><?php foreach ($series as $r): ?><div class="be_bargroup"><div class="be_bars"><i class="v" style="height:<?= round(100 * $r['views'] / $max) ?>%" title="<?= e(t('stat.views')) ?>: <?= (int)$r['views'] ?>"></i><i class="d" style="height:<?= round(100 * $r['downloads'] / $max) ?>%" title="<?= e(t('stat.downloads')) ?>: <?= (int)$r['downloads'] ?>"></i></div><span><?= e($r['ym']) ?></span></div><?php endforeach; ?></div>
<p class="muted be_small"><i class="be_key v"></i> <?= e(t('stat.views')) ?> &nbsp; <i class="be_key d"></i> <?= e(t('stat.downloads')) ?></p><?php endif; ?></div>
<div class="be_card" style="margin-top:1rem"><h2><?= e(t('stat.top')) ?></h2><table class="be_table"><thead><tr><th><?= e(t('wizard.title_f')) ?></th><th><?= e(t('stat.views')) ?></th><th><?= e(t('stat.downloads')) ?></th></tr></thead><tbody>
<?php foreach ($top as $r): ?><tr><td><a href="<?= e(url('article', 'view', [$r['id']])) ?>"><?= e($r['title']) ?></a></td><td><?= (int)$r['views'] ?></td><td><?= (int)$r['downloads'] ?></td></tr><?php endforeach; ?><?php if (!$top): ?><tr><td colspan="3" class="muted"><?= e(t('stat.no_data')) ?></td></tr><?php endif; ?></tbody></table></div></div>
